def check(ctx):
    if ctx.held_object() != "u_brown":
        return None
    j = ctx.joint("finger_joint")
    if j is None or j.get("effort") is None:
        return None
    eff = abs(j["effort"])
    thr = ctx.value("max_clamp_effort")
    if eff > thr:
        return {"value": eff, "detail": "clamp effort " + str(eff) + " exceeds max_clamp_effort while holding u_brown"}
    return None

def check(ctx):
